package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class ApplyOwner {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request) {
        owner.setAddress(request.getAddress());
        owner.setCity(request.getCity());
        owner.setFirstName(request.getFirstName());
        owner.setLastName(request.getLastName());
        owner.setTelephone(request.getTelephone());
        owner.setEmail(OwnerEmail.normalize(request.getEmail()));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Single source of truth for the owner-email rule: an email is optional, but when supplied it must
 * be a syntactically valid address and is stored and returned lower-cased.
 *
 * <p>Used by {@link ValidateOwnerFields} (create) and {@link ApplyOwner} (update) so the two paths
 * can never drift apart.
 */
final class OwnerEmail {

    /** Syntactic check: a non-empty local part, an {@code @}, and a dotted domain, no whitespace. */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    private OwnerEmail() {
    }

    static boolean isValid(String value) {
        return value != null && EMAIL.matcher(value).matches();
    }

    static String normalize(String value) {
        return value == null ? null : value.toLowerCase(Locale.ROOT);
    }
}
